import{_ as a,o as _,a as e,b as n}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"随路量化","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1788515292000}'),i={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization.md"};function o(d,t,r,l,s,c){return _(),e("div",null,[...t[0]||(t[0]=[n(`<div><article class="markdown-body"><h1>随路量化<span id="ZH-CN_TOPIC_0000002568950983"></span></h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中支持随路cast能力，cast mode为CAST_RINT模式。当L0C Buffer为float数据类型，输出为half/bfloat16数据类型，可以通过设置<strong>Fixpipe搬运参数结构体</strong>中的quantPre参数开启，或设置<strong>DataCopyCO12DstParams结构体参数</strong>中的quantPre参数开启，无需配置额外寄存器。使用cast输出half需配置为QuantMode_t::F322F16，使用cast输出bfloat16_t需配置为QuantMode_t::F322BF16。</p><p>同时矩阵计算的搬出过程中支持随路quant能力，当前支持两种模式的随路带参数的量化能力：</p><ul><li>同一系数（Scalar）的量化模式：整个C矩阵对应一个量化参数，量化参数的shape为[1]。可以通过设置quantPre参数，配置为对应的量化类型，若使用DataCopy实现矩阵搬出需要调用<a href="../cube_store_aux_config/SetFixpipePreQuantFlag.html">SetFixpipePreQuantFlag</a>接口来设置scalar量化参数，其中scalar量化参数QUANT_PRE为uint64_t类型，低32位表示的是float类型的量化系数（硬件以(1, 8, 10)的格式进行计算，即1个符号位、8个指数位和10个尾数位，4B），量化参数QUANT_PRE具体含义参见<a href="#zh-cn_topic_0000002547300781_table1273124313613">表1</a>。</li><li>向量（Tensor/Vector）的量化模式：C矩阵的shape为[m, n]，每个channel维度即C矩阵的每一列，对应一个量化参数，量化参数的shape为[n]。可以通过设置quantPre参数，配置为对应的量化类型，若使用DataCopy实现矩阵搬出需要调用<a href="../cube_store_aux_config/SetFixPipeConfig.html">SetFixPipeConfig</a>来设置tensor量化参数地址Quant_PRE_ADDR，其中tensor量化参数需要通过DataCopy从L1 Buffer搬运至Fixpipe Buffer。其中每个量化参数Quant_PRE_ADDR[i]为uint64_t类型（i为列索引），低32位表示的是float类型的量化系数（硬件以(1, 8, 10)的格式进行计算，即1个符号位、8个指数位和10个尾数位，4B）。量化参数Quant_PRE_ADDR[i]具体含义参见<a href="#zh-cn_topic_0000002547300781_table1273124313613">表1</a>。</li></ul><p>当前支持的量化模式及其功能描述如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>DEQF16,                // DeQuant_Float16：int32_t反量化成half，scalar量化
VDEQF16,               // Vector_DeQuant_Float16：int32_t反量化成half，tensor量化
QF322B8_PRE,           // Quant_Float32_2_B8：float量化成int8_t/uint8_t，scalar量化
VQF322B8_PRE,          // Vector_Quant_Float32_2_B8：float量化成int8_t/uint8_t，tensor量化
REQ8,                  // ReQuant_int8：int32_t重量化成int8_t/uint8_t，scalar量化
VREQ8,                 // Vector_ReQuant_int8：int32_t重量化成int8_t/uint8_t，tensor量化
</code></pre></div><div data-filter="950"><p>除上述量化模式外，Ascend 950PR/Ascend 950DT产品还额外支持以下量化模式：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>QF322FP8_PRE,          // Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，scalar量化
VQF322FP8_PRE,         // Vector_Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，tensor量化
QF322HIF8_PRE,         // Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，scalar量化
VQF322HIF8_PRE,        // Vector_Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，tensor量化
QF322HIF8_PRE_HYBRID,  // Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，scalar量化
VQF322HIF8_PRE_HYBRID, // Vector_Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，tensor量化
QS322BF16_PRE,         // Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，scalar量化
VQS322BF16_PRE,        // Vector_Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，tensor量化
QF322F16_PRE,          // Quant_Float32_2_Float16: float量化成half，scalar量化
VQF322F16_PRE,         // Vector_Quant_Float32_2_Float16: float量化成half，tensor量化
QF322BF16_PRE,         // Quant_Float32_2_BFloat16: float量化成bfloat16_t，scalar量化
VQF322BF16_PRE,        // Vector_Quant_Float32_2_BFloat16: float量化成bfloat16_t，tensor量化
QF322F32_PRE,          // Quant_Float32_2_Float32: float量化成float，scalar量化，精度可以达到双千分之一,无法达到双万分之一
VQF322F32_PRE,         // Vector_Quant_Float32_2_Float32: float量化成float，tensor量化，精度可以达到双千分之一,无法达到双万分之一
</code></pre></div></div><p>不同量化模式的量化算法详细介绍参见<a href="accompanying_quantization_and_relu_scenario_combination.html">随路量化与随路ReLU场景组合</a>。</p><div data-filter="950,A3,910b"><p>量化参数比特位含义见下表：</p><div data-filter="A3,910b"><p><strong>表1</strong> 量化参数QUANT_PRE比特位含义映射表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）<a id="zh-cn_topic_0000002547300781_table1273124313613"></a></p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>0~31</td><td>M1</td><td>32位数视为float，硬件以(1, 8, 10)的格式，即1个符号位、8个指数位和10个尾数位作为量化计算所需要乘的值。其中31位为符号位，23~30位为指数位，13~22位为尾数位。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>32~35</td><td>N</td><td>4位比特位，表示范围为[1, 16]（b&#39;0000对应表示1，b&#39;1111对应表示16）。<br>当模式为(V)REQ8时，MCB标志位置为1时，将输入的值进行右移N比特位。当模式为(V)QF322B8_PRE，N为无效变量。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>36</td><td>MCB标志位</td><td>Mode Control Bit。如果置为0，输入的int32_t会被直接转换为float，N为无效值。如果置为1，输入的int32_t会先右移N比特位，转变成int16_t，然后转换为float。当模式为(V)QF322B8_PRE时，此标志位为无效比特。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>37~45</td><td>Offset</td><td>9bit的整型数据，源数据乘以量化系数或者随路系数的计算结果，可以与Offset表示的整数值进行相加。若不使用offset，请置为0。<br>当模式为(V)DEQF16时，此变量为无效变量。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明量化结果是signed(int8)；如果置为0，表明量化结果是unsigned(uint8)。仅在(V)REQ8、(V)QF322B8_PRE中会用到。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>47~63</td><td>-</td><td>无效比特位，用户无需关注。</td></tr></tbody></table></div><div data-filter="950"><p><strong>表2</strong> 量化参数QUANT_PRE比特位含义映射表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）<a id="zh-cn_topic_0000002547300781_table1273124313714"></a></p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16<br>•(V)QF322FP8_PRE<br>•(V)QF322HIF8_PRE<br>•(V)QF322HIF8_PRE_HYBRID<br>•(V)QS322BF16_PRE<br>•(V)QF322F16_PRE<br>•(V)QF322BF16_PRE<br>•(V)QF322F32_PRE</td><td>0~12</td><td>-</td><td>无效比特位，用户无需关注。</td></tr><tr><td>同第一行</td><td>13~31</td><td>M1</td><td>数据类型视为float，硬件以(1, 8, 10)的格式，即1个符号位、8个指数位和10个尾数位作为量化计算所需要乘的值。其中31位为符号位，23~30位为指数位，13~22位为尾数位。其值不能为inf/nan。</td></tr><tr><td>同第一行</td><td>32~36</td><td>-</td><td>无效比特位，用户无需关注。</td></tr><tr><td>同第一行</td><td>37~45</td><td>Offset</td><td>9bit整形数据，源数据乘以量化系数或者随路系数的计算结果，可以与Offset表示的整数值进行相加。若不使用offset，请置为0。当模式为(V)REQ8、(V)QF322B8_PRE时该变量生效。</td></tr><tr><td>同第一行</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明量化结果是signed(int8)；如果为置为0，表明量化结果是unsigned(uint8)。仅在(V)REQ8、(V)QF322B8_PRE中会用到。</td></tr><tr><td>同第一行</td><td>47~63</td><td>-</td><td>无效比特位，用户无需关注。</td></tr></tbody></table></div></div><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2gm">fixpipe_l0c2gm样例</a>。</p></article></div>`,1)])])}const F=a(i,[["render",o]]);export{u as __pageData,F as default};
